import {readFileSync} from 'node:fs';
import {baseline,portfolio,withScenario,scenario,upstream,refresh,field,defect,reorder,cashBoundary} from './builders.mjs';
export const CAPACITY_PACK_VERSION='PRESCORE-DEBT-CAPACITY-RU-GOLDEN-1.0.0';
export function entries(){const es=[];const add=(n,title,input,expected)=>es.push({caseId:`CAP-RU-${String(n).padStart(3,'0')}`,revision:1,title,input,expected:{invariants:true,...expected}});
 add(1,'Twelve full stable months',baseline(),{status:'CALCULATED',prudential:200000,maximum:250000,fullMonths:12});
 add(2,'Six full months numeric partial',baseline({operating:Array(6).fill(1000000)}),{status:'PARTIAL',prudential:200000,fullMonths:6});
 add(3,'Five full months insufficient',baseline({operating:Array(5).fill(1000000)}),{status:'INSUFFICIENT_DATA',prudential:null});
 add(4,'Missing month is not zero',cashBoundary({coverage:['MISSING',...Array(11).fill('FULL')]}),{fullMonths:11,central:1000000,status:'PARTIAL',warnings:['MISSING_MONTH_NOT_ZERO']});
 add(5,'Partial spike excluded',cashBoundary({operating:[99000000,...Array(11).fill(1000000)],coverage:['PARTIAL',...Array(11).fill('FULL')]}),{fullMonths:11,central:1000000,prudential:200000});
 const future=baseline();future.bankMetrics.monthly.at(-1).month='2026-07';add(6,'Future month rejected',future,{invalid:'FUTURE_BANK_MONTH'});
 add(7,'Median limits one-off spike',baseline({operating:[...Array(11).fill(1000000),13000000]}),{central:1000000,conservative:1000000,prudential:200000});
 add(8,'Recent receipts decline',baseline({operating:[...Array(9).fill(1000000),500000,500000,500000]}),{central:875000,conservative:500000,prudential:100000});
 add(9,'Recent growth not extrapolated',baseline({operating:[...Array(9).fill(1000000),2000000,2000000,2000000]}),{central:1000000,conservative:1000000,prudential:200000});
 for(const[n,cat,title]of [[10,'OWNER_CONTRIBUTION','Owner funding excluded'],[11,'BANK_LOAN_RECEIVED','Bank loan inflow excluded'],[12,'FACTORING_PROCEEDS','Factoring inflow excluded'],[13,'ASSET_SALE_PROCEEDS','Asset sale excluded']])add(n,title,baseline({extraCategory:cat}),{central:1000000,prudential:200000,relative:[{other:'CAP-RU-001',field:'headroom',operator:'EQ'}]});
 add(14,'Known zero operating receipts',cashBoundary({operating:Array(12).fill(0)}),{central:0,prudential:0,maximum:0,state:'ZERO'});
 add(15,'Observed service below prudential ceiling',baseline({debt:Array(12).fill(100000)}),{observed:100000,prudential:100000,maximum:150000});
 add(16,'Existing service between twenty and twenty-five percent',baseline({debt:Array(12).fill(225000)}),{prudential:0,maximum:25000,state:'POSITIVE'});
 add(17,'Exactly twenty-five percent existing service',baseline({debt:Array(12).fill(250000)}),{prudential:0,maximum:0,state:'ZERO'});
 add(18,'Above twenty-five percent never negative',baseline({debt:Array(12).fill(300000)}),{prudential:0,maximum:0,state:'ZERO'});
 add(19,'Partial debt-service spike excluded',cashBoundary({debt:[99000000,...Array(11).fill(100000)],coverage:['PARTIAL',...Array(11).fill('FULL')]}),{observed:100000,prudential:100000});
 add(20,'Schedule lower than observed anchor',baseline({debt:Array(12).fill(100000),creditPortfolio:portfolio({payment:50000})}),{observed:100000,schedule:50000,nearAnchor:100000,prudential:100000});
 add(21,'Schedule higher than observed anchor',baseline({debt:Array(12).fill(100000),creditPortfolio:portfolio({payment:200000})}),{schedule:200000,nearAnchor:200000,prudential:0,maximum:50000});
 add(22,'Known maturity balloon payment within thirty days',baseline({creditPortfolio:portfolio({payment:1000000,due:'2026-07-30'})}),{schedule:1000000,prudential:0,maximum:0});
 add(23,'Day thirty-one outside near-term window',baseline({creditPortfolio:portfolio({payment:1000000,due:'2026-07-31'})}),{schedule:0,prudential:200000});
 add(24,'Closed obligation excluded',baseline({creditPortfolio:portfolio({status:'CLOSED'})}),{schedule:null,prudential:200000});
 add(25,'Bank guarantee payment excluded',baseline({creditPortfolio:portfolio({type:'BANK_GUARANTEE',payment:9999999})}),{schedule:null,prudential:200000});
 add(26,'Guarantorship excluded',baseline({creditPortfolio:portfolio({type:'GUARANTORSHIP',payment:9999999})}),{schedule:null,prudential:200000});
 const contingent=portfolio({type:'BANK_GUARANTEE'});contingent.obligations[0].currentTerms.guaranteeAmount.value=90000000;
 add(27,'Contingent amount is not monthly service',baseline({creditPortfolio:contingent}),{schedule:null,prudential:200000});
 add(28,'Leasing payment included',baseline({creditPortfolio:portfolio({type:'LEASING',payment:150000})}),{schedule:150000,prudential:50000});
 add(29,'Factoring not automatic funded debt',baseline({creditPortfolio:portfolio({type:'FACTORING',payment:9999999})}),{schedule:null,prudential:200000});
 add(30,'Unsplit payment counts only as observed cash service',baseline({debt:Array(12).fill(100000),debtCategory:'DEBT_SERVICE_UNSPLIT'}),{observed:100000,prudential:100000,warnings:['UNSPLIT_PAYMENT_NOT_PRINCIPAL_REDUCTION']});
 add(31,'No portfolio with strong bank evidence',baseline(),{status:'CALCULATED',schedule:null,prudential:200000});
 add(32,'Unknown supplied schedule is not zero',baseline({creditPortfolio:portfolio({noSchedule:true})}),{status:'PARTIAL',schedule:null,prudential:200000,warnings:['PORTFOLIO_SCHEDULE_INCOMPLETE']});
 add(33,'Partial Assessment caps completeness',upstream(34),{status:'PARTIAL',prudential:200000});
 add(34,'Insufficient Assessment has no normal capacity',upstream(35),{status:'INSUFFICIENT_DATA',prudential:null});
 const stop=upstream(11);stop.scenarios=[scenario()];add(35,'Global stop no headline or principal',stop,{status:'NOT_RATABLE_GLOBAL_STOP',prudential:null,scenarioPrincipal:null});
 add(36,'Low Readiness positive headroom',upstream(5),{readiness:'LOW',prudential:200000});
 const high=cashBoundary({debt:Array(12).fill(250000)});add(37,'High Readiness zero headroom',high,{readiness:'HIGH',prudential:0,maximum:0});
 const hi=baseline();hi.prescoreIndex.value=900;refresh(hi);add(38,'High Index has no capacity bonus',hi,{prudential:200000,relative:[{other:'CAP-RU-039',field:'headroom',operator:'EQ'}]});
 const lo=baseline();lo.prescoreIndex.value=600;refresh(lo);add(39,'Low Index has no capacity haircut',lo,{prudential:200000});
 add(40,'Data review is not monetary penalty',upstream(15),{prudential:200000,maximum:250000});
 add(41,'Explicit annuity discounted cash flows',withScenario(),{discounted:{payment:200000,rate:.01,months:12},scenarioCount:1});
 add(42,'Zero-rate principal equals payment times term',withScenario({annualRatePercent:0}),{scenarioPrincipal:2400000});
 add(43,'Higher rate lower equivalent',withScenario({annualRatePercent:24}),{relative:[{other:'CAP-RU-041',field:'principal',operator:'LT'}]});
 add(44,'Longer term larger equivalent',withScenario({termMonths:24}),{relative:[{other:'CAP-RU-041',field:'principal',operator:'GT'}]});
 const duplicate=withScenario();duplicate.scenarios.push(scenario());add(45,'Duplicate scenario rejected',duplicate,{invalid:'DUPLICATE_SCENARIO'});
 add(46,'Request within prudential modeled capacity',withScenario({annualRatePercent:0},{caseFields:{requestedAmount:field(1000000)}}),{coverage:'WITHIN_PRUDENTIAL_CAPACITY'});
 add(47,'Request between prudential and maximum',withScenario({annualRatePercent:0},{caseFields:{requestedAmount:field(2700000)}}),{coverage:'WITHIN_MAXIMUM_POLICY_CAPACITY'});
 add(48,'Request above modeled capacity',withScenario({annualRatePercent:0},{caseFields:{requestedAmount:field(4000000)}}),{coverage:'ABOVE_MODELED_CAPACITY'});
 add(49,'Requested term mismatch remains unknown',withScenario({termMonths:24},{caseFields:{requestedAmount:field(1000000)}}),{coverage:'UNKNOWN',scenarioWarnings:['SCENARIO_TERM_MISMATCH']});
 add(50,'Requested overdraft does not change annuity mechanics',withScenario({annualRatePercent:0},{caseFields:{requestedProduct:field('OVERDRAFT')}}),{scenarioPrincipal:2400000,prudential:200000,scenarioWarnings:['NOT_PRODUCT_RECOMMENDATION']});
 add(51,'Personal BKI does not penalize company capacity',upstream(31),{prudential:200000});
 add(52,'Historical zero overdue preserved',defect(),{defect:true,prudential:200000,observed:0});
 add(53,'Reordered inputs byte identical',reorder(baseline({creditPortfolio:portfolio({payment:100000})})),{relative:[{other:'CAP-RU-054',field:'output',operator:'EQ'}]});
 add(54,'Canonical source, multi-risk and portfolio pipeline',baseline({creditPortfolio:portfolio({payment:100000})}),{schedule:100000,prudential:100000});
 es.push({caseId:'CAP-RU-DEFECT-001',revision:1,title:'Permanent historical-zero current-overdue chain',input:defect(),expected:{invariants:true,defect:true,prudential:200000,observed:0}});return es;}
export function loadCapacityPack(){return {version:CAPACITY_PACK_VERSION,entries:entries(),fingerprints:JSON.parse(readFileSync(new URL('./fingerprints-v1.json',import.meta.url),'utf8'))};}
